INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'explorer', 'n.', '/ɪkˈsplɔːrə(r)/', '探险者;勘探者', 'The explorer led his men across the frozen sea.', '这位探险者带领队员们穿过结冰的海面。', 'Adventuring', 1, 0, 'senior', 'wordlist', 'elective1', 'U3', 'a polar explorer', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'pole', 'n.', '/pəʊl/', '(行星的)极;地极', 'Few people have ever reached the South Pole on foot.', '很少有人徒步到达过南极点。', 'Adventuring', 2, 0, 'senior', 'wordlist', 'elective1', 'U3', 'the South Pole', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'exceptionally', 'adv.', '/ɪkˈsepʃənəli/', '罕见地;特别地;非常', 'The winter on the ice was exceptionally cold and long.', '冰上的冬天异常寒冷而漫长。', 'Adventuring', 3, 0, 'senior', 'wordlist', 'elective1', 'U3', 'exceptionally cold', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'freezing', 'adj.', '/ˈfriːzɪŋ/', '极冷的;冰冻的', 'The men spent eight months in the freezing darkness.', '队员们在极冷的黑暗中度过了八个月。', 'Adventuring', 4, 0, 'senior', 'wordlist', 'elective1', 'U3', 'freezing cold', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'disaster', 'n.', '/dɪˈzɑːstə(r)/', '灾难;灾祸;灾害', 'Losing the ship in the ice was a real disaster for the crew.', '船陷在冰中是船员们真正的灾难。', 'Adventuring', 5, 0, 'senior', 'wordlist', 'elective1', 'U3', 'a natural disaster', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'crew', 'n.', '/kruː/', '(轮船、飞机等的)全体工作人员;船员', 'The crew worked day and night to save the ship.', '全体船员日夜不停地抢救这艘船。', 'Adventuring', 6, 0, 'senior', 'wordlist', 'elective1', 'U3', 'the whole crew', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'abandon', 'v.', '/əˈbændən/', '舍弃;离开;遗弃', 'They had no choice but to abandon the ship.', '他们别无选择,只能弃船。', 'Adventuring', 7, 0, 'senior', 'wordlist', 'elective1', 'U3', 'abandon ship', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'sink', 'v.', '/sɪŋk/', '下沉;沉没;下陷', 'The ship slowly began to sink under the ice.', '这艘船慢慢开始在冰下沉没。', 'Adventuring', 8, 0, 'senior', 'wordlist', 'elective1', 'U3', 'the ship sank', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'survive', 'v.', '/səˈvaɪv/', '幸存;生存;渡过难关', 'The men tried to survive by floating on the ice.', '队员们试图靠浮在冰上活下来。', 'Adventuring', 9, 0, 'senior', 'wordlist', 'elective1', 'U3', 'survive the cold', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'rescue', 'n./v.', '/ˈreskjuː/', '救援;营救;抢救', 'In that remote place there was no chance of rescue.', '在那个偏远的地方根本没有获救的机会。', 'Adventuring', 10, 0, 'senior', 'wordlist', 'elective1', 'U3', 'no chance of rescue', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'whaling', 'n.', '/ˈweɪlɪŋ/', '捕鲸(业)', 'He knew there was a whaling station where he could get help.', '他知道那里有个捕鲸站可以求助。', 'Adventuring', 11, 0, 'senior', 'wordlist', 'elective1', 'U3', 'a whaling station', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'march', 'v.', '/mɑːtʃ/', '(坚定地向某地)前进,进发', 'The men had to march continuously for many hours.', '队员们不得不连续行进许多个小时。', 'Adventuring', 12, 0, 'senior', 'wordlist', 'elective1', 'U3', 'march continuously', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'starve', 'v.', '/stɑːv/', '(使)挨饿;饿死', 'Anyone left in that place would starve to death.', '任何留在那里的人都会饿死。', 'Adventuring', 13, 0, 'senior', 'wordlist', 'elective1', 'U3', 'starve to death', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'frozen', 'adj.', '/ˈfrəʊzn/', '冻僵的;极冷的', 'Starved and frozen, they finally reached the station.', '又饿又冻,他们终于到达了那个站点。', 'Adventuring', 14, 0, 'senior', 'wordlist', 'elective1', 'U3', 'starved and frozen', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'sail', 'v./n.', '/seɪl/', '航行;乘船航行;帆', 'He set out again to sail round the continent.', '他再次出发,要乘船绕这片大陆航行。', 'Adventuring', 15, 0, 'senior', 'wordlist', 'elective1', 'U3', 'set sail', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'continent', 'n.', '/ˈkɒntɪnənt/', '大陆;陆地;洲', 'Antarctica is the coldest continent on the earth.', '南极洲是地球上最冷的大陆。', 'Adventuring', 16, 0, 'senior', 'wordlist', 'elective1', 'U3', 'the frozen continent', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'bury', 'v.', '/ˈberi/', '埋葬;安葬', 'The explorer was buried on a small southern island.', '这位探险者被安葬在一座南方小岛上。', 'Adventuring', 17, 0, 'senior', 'wordlist', 'elective1', 'U3', 'be buried in', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'exceptional', 'adj.', '/ɪkˈsepʃənl/', '杰出的;优秀的;卓越的', 'He showed exceptional leadership in the worst moments.', '在最艰难的时刻他展现出卓越的领导力。', 'Adventuring', 18, 0, 'senior', 'wordlist', 'elective1', 'U3', 'exceptional leadership', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'leadership', 'n.', '/ˈliːdəʃɪp/', '领导才能;领导;领导地位', 'The team survived because of his strong leadership.', '正是因为他强有力的领导,团队才得以幸存。', 'Adventuring', 19, 0, 'senior', 'wordlist', 'elective1', 'U3', 'strong leadership', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'voyage', 'n.', '/ˈvɔɪɪdʒ/', '航行;航海;航天', 'The young sailor was frightened on his first voyage.', '这位年轻水手在第一次航海中很害怕。', 'Adventuring', 20, 0, 'senior', 'wordlist', 'elective1', 'U3', 'a long voyage', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'impression', 'n.', '/ɪmˈpreʃn/', '印象;影响;效果', 'The great storm made a deep impression on him.', '那场大风暴给他留下了很深的印象。', 'Adventuring', 21, 0, 'senior', 'wordlist', 'elective1', 'U3', 'make an impression', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'sailor', 'n.', '/ˈseɪlə(r)/', '水手;海员', 'As a young sailor, he knew nothing about the sea.', '作为一个年轻水手,他对大海一无所知。', 'Adventuring', 22, 0, 'senior', 'wordlist', 'elective1', 'U3', 'a young sailor', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'dive', 'v.', '/daɪv/', '下潜;跳水;俯冲', 'Every time the ship dived down, he thought it would sink.', '每次船俯冲下去,他都以为它会沉没。', 'Adventuring', 23, 0, 'senior', 'wordlist', 'elective1', 'U3', 'dive down', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'depth', 'n.', '/depθ/', '深度;纵深;向下的距离', 'The boat dived into the depths of the huge waves.', '小船扎进了巨浪的深处。', 'Adventuring', 24, 0, 'senior', 'wordlist', 'elective1', 'U3', 'the depths of the sea', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'resolution', 'n.', '/ˌrezəˈluːʃn/', '决心;决定', 'During the storm he made a firm resolution to go home.', '在风暴中他下定决心要回家。', 'Adventuring', 25, 0, 'senior', 'wordlist', 'elective1', 'U3', 'make a resolution', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'resolve', 'v.', '/rɪˈzɒlv/', '决心;决定;解决(问题)', 'He resolved that he would never set sail again.', '他下决心再也不出海了。', 'Adventuring', 26, 0, 'senior', 'wordlist', 'elective1', 'U3', 'resolve to do', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'desperate', 'adj.', '/ˈdespərət/', '极危急的;不顾一切的;拼命的', 'He never wanted to be in such a desperate situation again.', '他再也不想陷入如此危急的处境。', 'Adventuring', 27, 0, 'senior', 'wordlist', 'elective1', 'U3', 'a desperate situation', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'plainly', 'adv.', '/ˈpleɪnli/', '清晰地;明显地;清楚地', 'Now he saw quite plainly that his father had been right.', '现在他十分清楚地看到父亲一直是对的。', 'Adventuring', 28, 0, 'senior', 'wordlist', 'elective1', 'U3', 'see plainly', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'observation', 'n.', '/ˌɒbzəˈveɪʃn/', '评论;观察;意见', 'He finally understood his father''s observation about life.', '他终于明白了父亲对人生的那番评论。', 'Adventuring', 29, 0, 'senior', 'wordlist', 'elective1', 'U3', 'make an observation', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'expose', 'v.', '/ɪkˈspəʊz/', '使面临;使遭受;暴露', 'His father had never been exposed to storms at sea.', '他父亲从未经受过海上的风暴。', 'Adventuring', 30, 0, 'senior', 'wordlist', 'elective1', 'U3', 'be exposed to', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'shore', 'n.', '/ʃɔː(r)/', '岸;滨', 'He had lived safely with no troubles on shore.', '他一直安稳地生活,在岸上没有任何麻烦。', 'Adventuring', 31, 0, 'senior', 'wordlist', 'elective1', 'U3', 'troubles on shore', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'last', 'v.', '/lɑːst/', '持续;延续', 'These anxious thoughts lasted while the storm went on.', '这些焦虑的想法在风暴持续期间一直存在。', 'Adventuring', 32, 0, 'senior', 'wordlist', 'elective1', 'U3', 'last for hours', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'indeed', 'adv.', '/ɪnˈdiːd/', '其实;实际上;的确', 'The fear lasted through the storm and indeed for some time afterwards.', '这种恐惧持续了整场风暴,其实之后还持续了一段时间。', 'Adventuring', 33, 0, 'senior', 'wordlist', 'elective1', 'U3', 'and indeed', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'persuade', 'v.', '/pəˈsweɪd/', '劝说;说服', 'His friend had persuaded him to go away to sea.', '他的朋友说服他出海远行。', 'Adventuring', 34, 0, 'senior', 'wordlist', 'elective1', 'U3', 'persuade sb to do', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'clap', 'v.', '/klæp/', '(友好地)轻拍;鼓掌', 'His friend clapped him on the shoulder and smiled.', '他的朋友拍了拍他的肩膀,笑了。', 'Adventuring', 35, 0, 'senior', 'wordlist', 'elective1', 'U3', 'clap sb on the shoulder', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'frightened', 'adj.', '/ˈfraɪtnd/', '害怕的;受惊的', 'I guess you were frightened last night during the storm.', '我猜你昨晚风暴时被吓到了。', 'Adventuring', 36, 0, 'senior', 'wordlist', 'elective1', 'U3', 'feel frightened', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'proof', 'n.', '/pruːf/', '证据;证明', 'His safe return was proof of his great courage.', '他平安归来证明了他非凡的勇气。', 'Adventuring', 37, 0, 'senior', 'wordlist', 'elective1', 'U3', 'give proof', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'dust', 'n./v.', '/dʌst/', '尘土;沙土;擦灰', 'Their tents and clothes were covered in ice and dust.', '他们的帐篷和衣服上覆满了冰和尘土。', 'Adventuring', 38, 0, 'senior', 'wordlist', 'elective1', 'U3', 'cover in dust', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'iron', 'n./v.', '/ˈaɪən/', '铁;熨斗;熨烫', 'Only a man with an iron will could finish such a march.', '只有意志如铁的人才能完成这样的行军。', 'Adventuring', 39, 0, 'senior', 'wordlist', 'elective1', 'U3', 'an iron will', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'energy', 'n.', '/ˈenədʒi/', '精力;能量;能源', 'The long climb used up the last of their energy.', '漫长的攀爬耗尽了他们最后的精力。', 'Adventuring', 40, 0, 'senior', 'wordlist', 'elective1', 'U3', 'use up energy', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'ski', 'v.', '/skiː/', '滑雪', 'Modern explorers sometimes ski across the white continent.', '现代探险者有时滑雪穿越这片白色大陆。', 'Adventuring', 41, 0, 'senior', 'wordlist', 'elective1', 'U3', 'ski across', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'surround', 'v.', '/səˈraʊnd/', '围绕;环绕', 'The tiny boat was surrounded by huge waves.', '那条小船被巨浪团团围住。', 'Adventuring', 42, 0, 'senior', 'wordlist', 'elective1', 'U3', 'be surrounded by', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'constant', 'adj.', '/ˈkɒnstənt/', '不变的;持续的;恒定的', 'The crew lived in constant danger on the ice.', '船员们在冰上一直处于持续的危险之中。', 'Adventuring', 43, 0, 'senior', 'wordlist', 'elective1', 'U3', 'constant danger', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'roof', 'n.', '/ruːf/', '屋顶;顶部', 'Antarctica is sometimes called the roof at the bottom of the world.', '南极洲有时被称为世界底端的屋顶。', 'Adventuring', 44, 0, 'senior', 'wordlist', 'elective1', 'U3', 'the roof of the world', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'border', 'n.', '/ˈbɔːdə(r)/', '边界;国界;边疆', 'They camped near the border of the moving ice.', '他们在移动的冰面边缘附近扎营。', 'Adventuring', 45, 0, 'senior', 'wordlist', 'elective1', 'U3', 'the border of the ice', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'normally', 'adv.', '/ˈnɔːməli/', '通常;正常情况下', 'Normally a ship would never sail into such icy waters.', '通常一艘船绝不会驶入这样的结冰水域。', 'Adventuring', 46, 0, 'senior', 'wordlist', 'elective1', 'U3', 'normally do', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'calm', 'adj.', '/kɑːm/', '(海洋)风平浪静的;平静的', 'The next day the wind died down and the sea became calm.', '第二天风停了,大海变得平静。', 'Adventuring', 47, 0, 'senior', 'wordlist', 'elective1', 'U3', 'a calm sea', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'rough', 'adj.', '/rʌf/', '(海)汹涌的;粗糙的;高低不平的', 'The sea had been so rough and terrible the day before.', '前一天大海是那么汹涌可怕。', 'Adventuring', 48, 0, 'senior', 'wordlist', 'elective1', 'U3', 'a rough sea', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'tent', 'n.', '/tent/', '帐篷;帐棚', 'They had no tent and could not stop to rest.', '他们没有帐篷,无法停下休息。', 'Adventuring', 49, 0, 'senior', 'wordlist', 'elective1', 'U3', 'put up a tent', NULL, 'sufe');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('se1u3.01', '①过去完成被动 had been done(过去某动作之前已被完成)', 'A2', 11, '上外版选择性必修第一册 U3 — 表示在过去某个时间/动作之前,某事已经被做完。结构 had been + 过去分词。常与 before/by the time/when（先发生）等连用:The ship had been crushed before they escaped.', 1, 'elective1', 'U3', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'sufe');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('se1u3.02', '②过去进行被动 was/were being done(过去某时正在被进行)', 'A2', 11, '上外版选择性必修第一册 U3 — 表示过去某一时刻某事正在被进行。结构 was/were being + 过去分词。常与 when/while/at that moment（同时点)连用:The boat was being repaired when the storm hit.', 2, 'elective1', 'U3', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'sufe');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('se1u3.03', '③两者辨析 + by 短语 / 含情态的被动', 'A2', 11, '上外版选择性必修第一册 U3 — 根据时间状语判定:某动作之前已完成→had been done;过去某刻正在进行→was/were being done;by 引出动作执行者;情态动词的被动用 modal + be done。', 3, 'elective1', 'U3', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'sufe');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U3' AND code='se1u3.01'), 'By the time Shackleton set out, twenty-eight men ____ from the applicants.', 'had been selected', 'were being selected', 'were selecting', 'had selected', 'A', 'By the time + 过去动作,选拔在那之前已完成 → 过去完成被动 had been + done。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U3' AND code='se1u3.01'), 'Before the storm hit, the lifeboats ____ and made ready on the deck.', 'were being prepared', 'had been prepared', 'were preparing', 'are prepared', 'B', 'Before + 过去动作,准备在那之前已完成 → had been + done。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U3' AND code='se1u3.01'), 'When the men reached the island, all their food ____ already.', 'was being eaten', 'was eating', 'had been eaten', 'has been eaten', 'C', 'already 强调在到达这一过去时点前食物已吃完 → had been + done。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U3' AND code='se1u3.01'), 'The route across the mountains ____ on foot by anyone before that day.', 'was never being crossed', 'never crossed', 'has never been crossed', 'had never been crossed', 'D', 'before that day 指过去时点之前,从未被穿越过 → 过去完成被动否定 had never been + done。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U3' AND code='se1u3.01'), 'By 1915 the ship ____ completely by the moving ice.', 'had been surrounded', 'was being surrounded', 'was surrounding', 'is surrounded', 'A', 'By 1915 表示到那个过去时间点为止,包围已完成 → had been + done。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U3' AND code='se1u3.01'), 'The captain found that his orders ____ before he even returned to camp.', 'were being carried out', 'had already been carried out', 'were carrying out', 'have been carried out', 'B', 'before he returned 之前命令已被执行 → had been + done。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U3' AND code='se1u3.01'), 'Two months earlier the broken ship ____ to the freezing sea.', 'was being abandoned', 'was abandoning', 'had been abandoned', 'abandoned', 'C', 'Two months earlier 指更早的过去,弃船动作已完成 → had been + done。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U3' AND code='se1u3.01'), 'When help finally came, three of the tents ____ by the wind.', 'were being torn down', 'were tearing down', 'are torn down', 'had been torn down', 'D', '在 help came 这一过去时点之前帐篷已被吹倒 → had been + done。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U3' AND code='se1u3.01'), 'Every survivor was amazed that the message ____ to the station before nightfall.', 'had been sent', 'was being sent', 'was sending', 'has been sent', 'A', 'before nightfall 这一过去界限之前消息已送达 → had been + done。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U3' AND code='se1u3.01'), 'By the second winter, the crew realised that they ____ by the rest of the world.', 'were being forgotten', 'had been forgotten', 'were forgetting', 'are forgotten', 'B', 'By the second winter 表示到过去那个点为止已被遗忘 → had been + done。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U3' AND code='se1u3.01'), 'The diary showed that a route ____ long before the men left the island.', 'was being planned', 'was planning', 'had been planned', 'has been planned', 'C', 'long before + 过去动作,计划早已被定好 → had been + done。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U3' AND code='se1u3.01'), 'After the boat sank, they learned that warm clothes ____ on board the night before.', 'were being left', 'were leaving', 'are left', 'had been left', 'D', 'the night before 指更早的过去,衣服已被落下 → had been + done。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U3' AND code='se1u3.01'), 'The rescue boat ____ by the Chilean government before the captain set off again.', 'had been provided', 'was being provided', 'was providing', 'has been provided', 'A', 'before the captain set off 之前船已被提供 → had been + done。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U3' AND code='se1u3.01'), 'When the sun rose, every man saw that the camp ____ by a thick layer of snow.', 'was being buried', 'had been buried', 'was burying', 'is buried', 'B', '在 sun rose 这一过去时点之前营地已被埋住 → had been + done。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U3' AND code='se1u3.01'), 'The explorer was proud that nobody ____ during the whole long expedition.', 'was being lost', 'was losing', 'had been lost', 'has been lost', 'C', 'the whole expedition 结束(过去)前无人丧生 → 过去完成被动 had been + done。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U3' AND code='se1u3.01'), 'By the time the ice melted, the lifeboats ____ down to the water''s edge.', 'were being dragged', 'were dragging', 'are dragged', 'had been dragged', 'D', 'By the time + 过去动作,救生艇在那之前已被拖到水边 → had been + done。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U3' AND code='se1u3.01'), 'He told us that the photographs ____ before the ship finally went down.', 'had been taken', 'were being taken', 'were taking', 'have been taken', 'A', 'before the ship went down 之前照片已被拍下 → had been + done。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U3' AND code='se1u3.01'), 'The men were relieved that a fire ____ by the time they crawled into the hut.', 'was being lit', 'had been lit', 'was lighting', 'is lit', 'B', 'by the time they crawled in 之前火已被点着 → had been + done。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U3' AND code='se1u3.01'), 'Before dawn broke, the heavy sledge ____ across the frozen ground.', 'was being pulled', 'was pulling', 'had been pulled', 'has been pulled', 'C', 'Before dawn broke 这一过去界限之前雪橇已被拉过去 → had been + done。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U3' AND code='se1u3.01'), 'By the next morning the wet ropes ____ as hard as iron.', 'were being frozen', 'were freezing', 'are frozen', 'had been frozen', 'D', 'By the next morning 指到过去那个早晨为止绳子已被冻硬 → had been + done。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U3' AND code='se1u3.02'), 'Great efforts ____ to free the ship when the ice suddenly broke in half.', 'were being made', 'had been made', 'were making', 'are being made', 'A', 'when 引出过去某刻,努力正在被进行 → 过去进行被动 were being + done。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U3' AND code='se1u3.02'), 'The lifeboat ____ when a huge wave struck it from the side.', 'had been repaired', 'was being repaired', 'was repairing', 'is being repaired', 'B', 'when 引出过去同一时点,修理正在被进行 → was being + done。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U3' AND code='se1u3.02'), 'While the supplies ____ onto the boats, the wind began to rise.', 'had been loaded', 'were loading', 'were being loaded', 'are being loaded', 'C', 'While + 过去进行,补给正在被搬上船 → were being + done。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U3' AND code='se1u3.02'), 'At that very moment the tents ____ against the freezing wind.', 'had been put up', 'were putting up', 'are being put up', 'were being put up', 'D', 'At that very moment 强调过去某刻正在进行 → were being + done。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U3' AND code='se1u3.02'), 'The injured man''s leg ____ when the doctor''s hands grew too cold to work.', 'was being treated', 'had been treated', 'was treating', 'is being treated', 'A', 'when 引出过去同一时点,治疗正在被进行 → was being + done。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U3' AND code='se1u3.02'), 'As the documentary explained, the explorers ____ to the very limits of human endurance.', 'had been pushed', 'were being pushed', 'were pushing', 'are being pushed', 'B', '叙述过去那段时间持续正在被推向极限 → were being + done。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U3' AND code='se1u3.02'), 'When I looked out of the hut, the dogs ____ for the long journey ahead.', 'had been harnessed', 'were harnessing', 'were being harnessed', 'are being harnessed', 'C', 'When I looked out 引出过去某刻,套挽具正在被进行 → were being + done。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U3' AND code='se1u3.02'), 'The captain''s plan ____ over and over while the men waited on the ice.', 'had been discussed', 'was discussing', 'is being discussed', 'was being discussed', 'D', 'while + 过去进行,计划正在被反复讨论 → was being + done。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U3' AND code='se1u3.02'), 'Just as the storm reached the boat, the sails ____ to slow it down.', 'were being lowered', 'had been lowered', 'were lowering', 'are being lowered', 'A', 'Just as 引出过去同一时点,船帆正在被放下 → were being + done。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U3' AND code='se1u3.02'), 'While fresh water ____ from the melting snow, the men sang to keep warm.', 'had been collected', 'was being collected', 'was collecting', 'is being collected', 'B', 'While + 过去进行,淡水正在被收集 → was being + done。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U3' AND code='se1u3.02'), 'The wireless ____ when the last of the batteries finally died.', 'had been used', 'was using', 'was being used', 'is being used', 'C', 'when 引出过去某刻,无线电正在被使用 → was being + done。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U3' AND code='se1u3.02'), 'At nine o''clock the heavy boat ____ across the rocks towards the open sea.', 'had been carried', 'was carrying', 'is being carried', 'was being carried', 'D', 'At nine o''clock 指过去具体时刻正在进行 → was being + done。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U3' AND code='se1u3.02'), 'While the route ____ on the map, a fresh snowstorm closed in.', 'was being marked', 'had been marked', 'was marking', 'is being marked', 'A', 'While + 过去进行,路线正在被标在地图上 → was being + done。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U3' AND code='se1u3.02'), 'The frozen meat ____ slowly over the fire when a gust blew the flames out.', 'had been warmed', 'was being warmed', 'was warming', 'is being warmed', 'B', 'when 引出过去同一时点,肉正在被加热 → was being + done。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U3' AND code='se1u3.02'), 'As night fell, the last messages ____ down in the captain''s log.', 'had been written', 'were writing', 'were being written', 'are being written', 'C', 'As night fell 引出过去某刻正在进行 → were being + done。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U3' AND code='se1u3.02'), 'The sick sailor ____ below deck while the others fought the rising waves.', 'had been looked after', 'was looking after', 'is being looked after', 'was being looked after', 'D', 'while + 过去进行,病人正在被照料 → was being + done。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U3' AND code='se1u3.02'), 'When the rescuers arrived, a signal fire ____ on the highest point of the island.', 'was being kept', 'had been kept', 'was keeping', 'is being kept', 'A', 'When the rescuers arrived 引出过去某刻,信号火正在被维持 → was being + done。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U3' AND code='se1u3.02'), 'While the photographs ____ from the wreck, the ice cracked beneath their feet.', 'had been saved', 'were being saved', 'were saving', 'are being saved', 'B', 'While + 过去进行,照片正在被抢救 → were being + done。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U3' AND code='se1u3.02'), 'At dawn the small boat ____ towards the distant whaling station.', 'had been rowed', 'was rowing', 'was being rowed', 'is being rowed', 'C', 'At dawn 指过去某刻正在进行,小船正在被划 → was being + done。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U3' AND code='se1u3.02'), 'While the deck ____ clear of snow, a huge wave swept right over the men.', 'had been cleared', 'was clearing', 'is being cleared', 'was being cleared', 'D', 'While + 过去进行,甲板正在被清扫 → was being + done。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U3' AND code='se1u3.03'), 'The expedition ship ____ by the accident long before it reached the sea.', 'had been delayed', 'was being delayed', 'was delaying', 'is delayed', 'A', 'long before + 过去动作,延误早已发生 → 过去完成被动 had been + done。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U3' AND code='se1u3.03'), 'Preparations ____ for the rescue when news of the storm arrived.', 'had been made', 'were being made', 'were making', 'are being made', 'B', 'when 引出过去同一时点,准备正在被进行 → 过去进行被动 were being + done。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U3' AND code='se1u3.03'), 'Every member of the crew ____ by Shackleton himself before the voyage began.', 'was being chosen', 'was choosing', 'had been chosen', 'is chosen', 'C', 'before the voyage began 之前已被本人挑选,by 引出执行者 → had been + done。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U3' AND code='se1u3.03'), 'When we got there, the wounded explorer ____ by two of his friends.', 'had been carried', 'was carrying', 'is being carried', 'was being carried', 'D', 'When we got there 引出过去某刻,正被两位朋友抬着 → was being + done。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U3' AND code='se1u3.03'), 'The whole story ____ in his diary years before it was finally published.', 'had been recorded', 'was being recorded', 'was recording', 'is recorded', 'A', 'years before + 过去动作,故事早已被记录 → had been + done。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U3' AND code='se1u3.03'), 'The signal ____ by the watchman the moment the rescue boat appeared.', 'had been raised', 'was being raised', 'was raising', 'is being raised', 'B', 'the moment 引出过去同一时点,信号正被升起,by 引出执行者 → was being + done。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U3' AND code='se1u3.03'), 'Nothing ____ public about the men until they had safely come home.', 'was being made', 'was making', 'had been made', 'is made', 'C', 'until 之前(过去)什么都没被公开 → had been + done。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U3' AND code='se1u3.03'), 'Heavy sledges ____ over the mountains by the exhausted men at that time.', 'had been dragged', 'were dragging', 'are being dragged', 'were being dragged', 'D', 'at that time 指过去某刻正在进行,by 引出执行者 → were being + done。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U3' AND code='se1u3.03'), 'Anyone left in that place ____ to death, the captain knew, unless help came.', 'would be starved', 'had been starved', 'was being starved', 'is starved', 'A', '情态语气表对将来后果的判断 → 情态被动 would be + done。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U3' AND code='se1u3.03'), 'The captain warned that the boat ____ by the rocks if they steered too close.', 'had been smashed', 'might be smashed', 'was being smashed', 'is smashed', 'B', 'if 条件下的可能后果 → 情态被动 might be + done。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U3' AND code='se1u3.03'), 'By the time the sun came out, the broken mast ____ with rope and wood.', 'was being repaired', 'was repairing', 'had been repaired', 'is repaired', 'C', 'By the time + 过去动作,桅杆在那之前已被修好 → had been + done。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U3' AND code='se1u3.03'), 'As the camera turned, fresh supplies ____ onto the tiny lifeboat by the sailors.', 'had been loaded', 'were loading', 'are being loaded', 'were being loaded', 'D', 'As the camera turned 引出过去某刻正在进行,by 引出执行者 → were being + done。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U3' AND code='se1u3.03'), 'The route ____ on foot by anyone in history before Shackleton''s men crossed it.', 'had never been explored', 'was never being explored', 'never explored', 'is never explored', 'A', 'before + 过去动作,历史上从未被徒步探索过 → 过去完成被动否定 had never been + done。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U3' AND code='se1u3.03'), 'While the documentary ____ , old sailors shared memories of the great voyage.', 'had been filmed', 'was being filmed', 'was filming', 'is being filmed', 'B', 'While + 过去进行,纪录片正在被拍摄 → was being + done。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U3' AND code='se1u3.03'), 'The plan to cross the island ____ by the captain before anyone else woke up.', 'was being worked out', 'was working out', 'had been worked out', 'is worked out', 'C', 'before anyone woke up 之前计划已被想出,by 引出执行者 → had been + done。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U3' AND code='se1u3.03'), 'The frightened sailor felt the ship ____ down into the depths of each wave.', 'had been dragged', 'was dragging', 'is being dragged', 'was being dragged', 'D', '感官动词后表过去某刻正在被进行 → was being + done。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U3' AND code='se1u3.03'), 'All the lifeboats ____ from the wreck long before the ship sank for good.', 'had been saved', 'were being saved', 'were saving', 'are saved', 'A', 'long before + 过去动作,救生艇早已被救出 → had been + done。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U3' AND code='se1u3.03'), 'The good news ____ across the deck just as the men sat down to rest.', 'had been spread', 'was being spread', 'was spreading', 'is being spread', 'B', 'just as 引出过去同一时点,好消息正在被传开 → was being + done。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U3' AND code='se1u3.03'), 'Without his leadership, the men ____ on that island, the historian noted.', 'were being lost', 'had lost', 'might have been lost', 'are lost', 'C', '对过去未发生情况的推测 → 情态完成被动 might have been + done。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U3' AND code='se1u3.03'), 'The brave story ____ down from sailor to sailor long after the captain died.', 'was being handed', 'was handing', 'is handed', 'had been handed', 'D', 'long after + 过去动作,在更早过去之前故事已被代代相传 → had been + done。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'A Leader Who Brought Everyone Home', 'Ernest Shackleton is remembered as one of the greatest polar explorers, yet his most famous journey was, in a way, a failure. In 1914 he set out to cross Antarctica, the coldest continent on the earth. His ship never reached land. It became stuck in the ice and was slowly crushed before it sank. What makes the story remarkable is not the goal he missed but the way he brought every single man home alive. For nearly two years the crew lived in constant danger, short of food and warmth. Again and again Shackleton put his men before himself, sharing his food and hiding his own fear. He pushed on across freezing seas and icy mountains so that others could be rescued. People today look up to him as a hero, not because he won, but because of his exceptional leadership when everything went wrong. His example reminds us that true courage is often shown in how we deal with failure.', '人物·杰出领导力', 161, '[{"q":"Why is Shackleton''s most famous journey described as a failure?","answer":"A","options":["His ship was lost and he never reached the land he aimed for.","All of his men died on the ice.","He refused to share food with the crew.","He gave up exploring after one winter."],"explanation":"原文说船陷冰、沉没、never reached land,目标未达成;其余与原文相反。"},{"q":"What does the text say truly made Shackleton a hero?","answer":"B","options":["The speed at which he crossed Antarctica.","The way he led his men through disaster and saved them all.","The money he made from the trip.","The fame he gained before the voyage."],"explanation":"原文强调 exceptional leadership 与把全员带回,是 brought everyone home 的转述。"},{"q":"What lesson does the writer draw from the story?","answer":"A","options":["Real courage often shows in how a person handles failure.","Only winners deserve to be remembered.","Exploring is too dangerous to try.","Leaders should always put themselves first."],"explanation":"末句 true courage is often shown in how we deal with failure 的转述。"}]'::jsonb, '[{"word":"explorer","cn":"探险者"},{"word":"continent","cn":"大陆"},{"word":"leadership","cn":"领导力"}]'::jsonb, 2, 'elective1', 'U3', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'Trapped in the Ice', 'In January 1915 the ship known as the Endurance got stuck fast in the frozen Weddell Sea. The crew had hoped to sail close to land, but the ice closed in around them and would not let go. For month after month the men waited, living in the dark and the bitter cold. They played games, looked after the dogs, and tried to keep their spirits up, but everyone knew the danger was growing. As spring came, the moving ice began to press harder against the wooden ship. At last the great pressure broke the Endurance apart, and it slowly went down beneath the surface. The men were now alone on the ice, far from any help. They saved three small lifeboats and a little food from the wreck. With no land in sight, they camped on the ice and let it carry them slowly north. It was a frightening time, but they refused to give up hope of being saved.', '事件·坚忍号被困', 161, '[{"q":"What happened to the Endurance in the end?","answer":"B","options":["It safely sailed back to land.","The pressure of the ice broke it and it sank.","It was set on fire by the crew.","It was pulled out by another ship."],"explanation":"原文 the great pressure broke the Endurance apart, and it slowly went down 的转述。"},{"q":"How did the crew spend the long months trapped in the ice?","answer":"C","options":["They quickly built a new ship.","They split up and walked away alone.","They kept busy and tried to stay hopeful despite the danger.","They gave up and stopped caring for the animals."],"explanation":"原文 played games, looked after the dogs, tried to keep their spirits up 的概括。"},{"q":"What did the men do after the ship was lost?","answer":"D","options":["They immediately walked across to the South Pole.","They returned at once to the warm cabins.","They sailed straight to a whaling station.","They set up camp and let the moving ice carry them northward."],"explanation":"原文 camped on the ice and let it carry them slowly north 的转述。"}]'::jsonb, '[{"word":"crew","cn":"全体船员"},{"word":"frozen","cn":"冰冻的"},{"word":"lifeboat","cn":"救生艇"}]'::jsonb, 2, 'elective1', 'U3', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'The March Across South Georgia', 'After an open-boat journey of more than a thousand kilometres, Shackleton and five men finally reached South Georgia. Their suffering was far from over. The whaling station, where help waited, lay on the other side of a wild, mountainous island. No one had ever crossed it on foot before. With no tent and almost no food, the small group set off into the unknown. For about thirty-six hours they marched without stopping. They could not rest for more than a few minutes, for if they fell asleep in the cold they might never wake again. They climbed icy slopes, slid down snowfields, and pushed on through thick fog. Hungry, frozen, and close to the end of their strength, the three men who were strong enough at last stumbled down to the station. The whalers could hardly believe that anyone had survived such a march. Help was now within reach, and the long fight to save the others on Elephant Island could begin.', '事件·徒步横穿南乔治亚岛', 162, '[{"q":"Why was crossing South Georgia so dangerous?","answer":"A","options":["It was a wild mountain island no one had crossed on foot, and they had no shelter.","It was full of wild animals that attacked travellers.","The whaling station kept moving away from them.","They had too much food to carry over the hills."],"explanation":"原文说无人徒步穿越过、no tent、mountainous,是综合转述。"},{"q":"Why could the men not stop to rest properly?","answer":"B","options":["The whalers had told them to hurry for fun.","Falling asleep in the cold could mean they would die.","There were too many tourists on the path.","Their boat was waiting just behind them."],"explanation":"原文 if they fell asleep in the cold they might never wake again 的转述。"},{"q":"How did the whalers react when the men arrived?","answer":"C","options":["They refused to let the men in.","They had been expecting them for weeks.","They were amazed that anyone could survive such a journey.","They thought the men had taken an easy route."],"explanation":"原文 could hardly believe that anyone had survived such a march 的转述。"}]'::jsonb, '[{"word":"march","cn":"行进"},{"word":"whaling","cn":"捕鲸的"},{"word":"frozen","cn":"冻僵的"}]'::jsonb, 2, 'elective1', 'U3', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'My First Storm at Sea', 'When I first went to sea as a young sailor, I knew nothing about ships or storms. On only my second day, the wind rose and the waves grew higher and higher. To me they looked like mountains of water. Every time the ship dived into the deep valley between two waves, I was sure we would never rise again. In my fear I made many promises. If only my life could be spared, I said to myself, I would go straight home to my father and never set sail again. I now saw plainly how wise his advice had been and how safe his quiet life on shore really was. Yet the next day the wind died away and the sea became calm and beautiful. The sun shone on the smooth water, and the whole sight seemed the finest I had ever seen. My fear faded as quickly as the storm. When my friend came up and laughed at my fright, I almost forgot all the promises I had made the night before.', '文学·初次航海的恐惧', 174, '[{"q":"How did the young sailor feel during the storm?","answer":"D","options":["He felt calm and enjoyed the high waves.","He was proud of his skill at sea.","He was bored and wanted more excitement.","He was terrified and regretted ever going to sea."],"explanation":"原文描述他害怕、后悔、想回家;其余与原文相反。"},{"q":"What promise did the sailor make during the storm?","answer":"A","options":["To return home to his father and stop sailing.","To become the captain of his own ship.","To sail even further the next year.","To teach others how to face storms."],"explanation":"原文 go straight home to my father and never set sail again 的转述。"},{"q":"What happened to his fear the following day?","answer":"B","options":["It grew much stronger overnight.","It disappeared as the sea grew calm and lovely.","It stayed exactly the same.","It turned into anger at his friend."],"explanation":"原文说风停海平、My fear faded as quickly as the storm。"}]'::jsonb, '[{"word":"sailor","cn":"水手"},{"word":"plainly","cn":"清楚地"},{"word":"calm","cn":"平静的"}]'::jsonb, 2, 'elective1', 'U3', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'Why Do People Explore?', 'Why do people leave warm homes to face danger in far-off places? Long ago, our ancestors wondered what lay on the other side of the sky and beyond the distant hills. That same wonder still drives us today. Some explorers are searching for knowledge. They want to understand how the world works, from the deepest oceans to the highest mountains. Others are drawn by the simple wish to be the first, to stand where no human foot has stood before. There are also those who explore to test themselves, to find out just how much hardship their bodies and minds can bear. Of course, exploring is rarely safe. People may be hurt, lost, or worse. Yet history shows that humans have never been willing to stay still. Each new place we reach opens a door to questions we did not even know how to ask. As long as there is an unknown world out there, someone, somewhere, will always want to set out and discover it.', '议论·探险的理由', 166, '[{"q":"According to the text, what is one reason people explore?","answer":"C","options":["To avoid ever learning anything new.","To stay safely at home forever.","To gain knowledge about how the world works.","To make sure no one travels at all."],"explanation":"原文 searching for knowledge, want to understand how the world works 的转述。"},{"q":"What does the writer say about the danger of exploring?","answer":"D","options":["It no longer exists in modern times.","It keeps almost everyone at home.","It only affects machines, not people.","It is real, yet it has never stopped people from setting out."],"explanation":"原文承认 rarely safe 但 humans have never been willing to stay still。"},{"q":"What does each newly reached place do, according to the passage?","answer":"A","options":["It opens up fresh questions people had not thought of before.","It answers every question once and for all.","It makes future exploring pointless.","It closes the door on all curiosity."],"explanation":"原文 opens a door to questions we did not even know how to ask 的转述。"}]'::jsonb, '[{"word":"explore","cn":"探索"},{"word":"hardship","cn":"艰难"},{"word":"unknown","cn":"未知的"}]'::jsonb, 2, 'elective1', 'U3', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'Polar Explorers Today', 'Modern explorers no longer travel in wooden ships that can be crushed by the ice. Instead, they use light sledges, warm tents, and clothing designed for the coldest weather on the earth. Some of them ski across the frozen continent, pulling everything they need behind them. Others ride special vehicles that can move over deep snow without sinking. Radios and satellites mean that, unlike Shackleton''s crew, today''s teams can call for rescue if something goes wrong. Yet the polar world is still one of the most dangerous places a person can go. Storms appear without warning, and the cold can freeze skin in minutes. Cracks may open in the ice without a sound, and a single mistake can cost a life. For this reason, careful planning matters as much as courage. Modern adventurers study the weather, test their gear, and train their bodies for months before they set out. Better tools have made polar travel safer, but they have not removed the need for the strong spirit that drove earlier explorers.', '现代·当代极地探险', 171, '[{"q":"How is travel for modern polar explorers different from Shackleton''s day?","answer":"B","options":["They face no cold or storms at all.","They have better gear and can call for help by radio or satellite.","They still sail in wooden ships through the ice.","They never need to plan their journeys."],"explanation":"原文 radios and satellites... can call for rescue 及更好装备的转述。"},{"q":"Why is the polar world still described as very dangerous?","answer":"C","options":["The ice has become warm and soft.","There are crowds of tourists everywhere.","Sudden storms, deep cold, and hidden cracks can quickly kill.","Modern tools never break down."],"explanation":"原文列举 storms without warning、cold freezes skin、cracks open。"},{"q":"What does the writer say is still needed besides good tools?","answer":"D","options":["A faster way to skip all planning.","A guarantee that nothing will go wrong.","A warmer climate at the poles.","The strong spirit that earlier explorers had."],"explanation":"末句 have not removed the need for the strong spirit 的转述。"}]'::jsonb, '[{"word":"sledge","cn":"雪橇"},{"word":"frozen","cn":"冰冻的"},{"word":"rescue","cn":"救援"}]'::jsonb, 2, 'elective1', 'U3', 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective1', 'U3', 'Choosing the Team', 'Before any great expedition can begin, a leader must (1)____ the right people. When Shackleton planned his trip, hundreds of men wrote to him, all (2)____ to join. He could not take everyone, so he had to be very (3)____. He did not only look at how strong a man was. He also wanted to know whether someone could stay (4)____ in danger and work well with others. A team that argues will soon (5)____ apart. Each man chosen had a clear (6)____ to do, such as caring for the dogs or cooking the food. Shackleton believed that a happy crew had a better (7)____ of staying alive. He even valued men who could sing or tell jokes, because laughter helped people (8)____ the long, dark days. In the end, the men he picked were not only (9)____, but also kind and patient. That careful choice was one (10)____ why so many of them came home alive.', 157, 2, '[{"q":"1","answer":"A","options":["choose","forget","lose","waste"],"explanation":"choose the right people 挑选合适的人。"},{"q":"2","answer":"B","options":["afraid","eager","unable","slow"],"explanation":"eager to join 渴望加入。"},{"q":"3","answer":"C","options":["lazy","rude","careful","noisy"],"explanation":"be very careful 非常谨慎。"},{"q":"4","answer":"D","options":["angry","asleep","lost","calm"],"explanation":"stay calm in danger 危险中保持镇定。"},{"q":"5","answer":"A","options":["fall","grow","build","stand"],"explanation":"fall apart 散伙、瓦解。"},{"q":"6","answer":"B","options":["game","job","song","meal"],"explanation":"a clear job to do 明确的任务。"},{"q":"7","answer":"C","options":["price","noise","chance","size"],"explanation":"a better chance of staying alive 更大的生还机会。"},{"q":"8","answer":"D","options":["enjoy","buy","count","bear"],"explanation":"bear the long days 熬过漫长的日子。"},{"q":"9","answer":"A","options":["strong","weak","silent","famous"],"explanation":"not only strong but also kind 不仅强壮。"},{"q":"10","answer":"B","options":["minute","reason","step","place"],"explanation":"one reason why 之所以……的一个原因。"}]'::jsonb, 1, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective1', 'U3', 'Living Through the Polar Night', 'For weeks the sun did not rise at all, and the men lived in (1)____ darkness. The cold was so (2)____ that breath turned to ice on their beards. To pass the time, they read aloud, played cards, and (3)____ stories of home. Keeping busy was important, because too much (4)____ time made the danger feel even worse. Every day someone had to break the ice to find fresh (5)____ to drink. The dogs needed feeding, and the boats had to be (6)____ from the moving ice. Shackleton made sure that each man kept a daily (7)____, so that nobody felt useless. He knew that a person who has nothing to do soon loses (8)____. When a small problem appeared, he dealt with it (9)____, before it could grow into a real disaster. Slowly, the days began to lengthen again, and a thin line of light returned to the (10)____. Hope came back with the sun.', 156, 2, '[{"q":"1","answer":"C","options":["bright","warm","complete","empty"],"explanation":"complete darkness 完全的黑暗。"},{"q":"2","answer":"D","options":["gentle","lovely","useful","bitter"],"explanation":"so bitter (cold) 刺骨地冷。"},{"q":"3","answer":"A","options":["shared","sold","burnt","lost"],"explanation":"shared stories 分享故事。"},{"q":"4","answer":"B","options":["school","free","summer","boat"],"explanation":"too much free time 太多空闲时间。"},{"q":"5","answer":"C","options":["money","music","water","paper"],"explanation":"fresh water to drink 可饮用的淡水。"},{"q":"6","answer":"D","options":["thrown","sold","painted","protected"],"explanation":"protected from the ice 保护以防冰挤。"},{"q":"7","answer":"A","options":["task","joke","song","prize"],"explanation":"a daily task 每日的任务。"},{"q":"8","answer":"B","options":["weight","hope","speed","colour"],"explanation":"loses hope 失去希望。"},{"q":"9","answer":"C","options":["rarely","lazily","quickly","loudly"],"explanation":"dealt with it quickly 迅速处理。"},{"q":"10","answer":"D","options":["boat","tent","dog","sky"],"explanation":"a line of light returned to the sky 天空中重现光线。"}]'::jsonb, 2, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective1', 'U3', 'The Open-Boat Journey', 'There was no hope of (1)____ on the lonely island, so Shackleton decided to sail for help. He chose five men to go with him in a tiny (2)____ only seven metres long. The sea in that part of the world is among the most (3)____ on the earth, with waves as tall as houses. Day and night the little boat was (4)____ by huge waves, and freezing water poured over the men. They were always wet, always cold, and could hardly (5)____. To find their way, the captain used the sun whenever the clouds (6)____ for a moment. One wrong turn could mean they would never (7)____ land at all. After about two weeks of this terrible (8)____, they finally saw the dark shape of the island ahead. Even then, the rough sea would not let them (9)____ for two more days. When at last they stepped onto the rocks, they could hardly (10)____, but they were alive.', 159, 2, '[{"q":"1","answer":"A","options":["rescue","summer","music","rest"],"explanation":"no hope of rescue 没有获救的希望。"},{"q":"2","answer":"B","options":["house","boat","train","shop"],"explanation":"a tiny boat 一条小艇。"},{"q":"3","answer":"C","options":["peaceful","shallow","dangerous","warm"],"explanation":"the most dangerous seas 最危险的海域。"},{"q":"4","answer":"D","options":["ignored","warmed","sold","surrounded"],"explanation":"surrounded by huge waves 被巨浪包围。"},{"q":"5","answer":"A","options":["sleep","swim","fly","drive"],"explanation":"could hardly sleep 几乎无法入睡。"},{"q":"6","answer":"B","options":["froze","cleared","grew","fell"],"explanation":"the clouds cleared 云散开(才能用太阳定位)。"},{"q":"7","answer":"C","options":["build","buy","reach","paint"],"explanation":"never reach land 永远到不了陆地。"},{"q":"8","answer":"D","options":["lesson","meal","game","voyage"],"explanation":"this terrible voyage 这次可怕的航行。"},{"q":"9","answer":"A","options":["land","sing","sleep","win"],"explanation":"would not let them land 不让他们登陆。"},{"q":"10","answer":"B","options":["read","stand","cook","drive"],"explanation":"could hardly stand 几乎站不稳。"}]'::jsonb, 3, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective1', 'U3', 'Marching Through the Night', 'Once on the island, the men still had to cross high mountains to (1)____ the whaling station. They had almost no food and no (2)____ to sleep in. To stop and rest for long would be (3)____, because anyone who fell asleep in the cold might never wake. So they kept walking, hour after (4)____ hour. The ground was covered in deep snow, and thick fog made it hard to (5)____ the way. Sometimes they slid down icy slopes, hoping they would not fall off a cliff in the (6)____. Their bodies were so tired that every step took great (7)____. Yet the thought of their friends waiting for help gave them the (8)____ to go on. After about thirty-six hours, they (9)____ heard the sound of the station whistle far below. That sound told them their long march was nearly (10)____, and help was finally close.', 147, 2, '[{"q":"1","answer":"C","options":["leave","lose","reach","build"],"explanation":"reach the station 到达站点。"},{"q":"2","answer":"D","options":["boat","car","shop","tent"],"explanation":"no tent to sleep in 没有可睡的帐篷。"},{"q":"3","answer":"A","options":["deadly","easy","boring","funny"],"explanation":"would be deadly 会致命。"},{"q":"4","answer":"B","options":["happy","weary","sunny","lazy"],"explanation":"hour after weary hour 一个接一个疲惫的小时。"},{"q":"5","answer":"C","options":["eat","sell","see","sing"],"explanation":"hard to see the way 难以看清道路。"},{"q":"6","answer":"D","options":["shop","sun","boat","fog"],"explanation":"fall off a cliff in the fog 在雾中坠崖。"},{"q":"7","answer":"A","options":["effort","money","music","noise"],"explanation":"took great effort 费很大力气。"},{"q":"8","answer":"B","options":["weight","strength","size","price"],"explanation":"gave them the strength to go on 给他们继续的力量。"},{"q":"9","answer":"C","options":["rarely","hardly","finally","never"],"explanation":"finally heard 终于听到。"},{"q":"10","answer":"D","options":["lost","wrong","empty","over"],"explanation":"the march was nearly over 行军快结束了。"}]'::jsonb, 4, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective1', 'U3', 'Going Back for the Others', 'Reaching safety was not the end of Shackleton''s story. Twenty-three men were still (1)____ on the cold island far away, and he had promised to bring them home. Three times he tried to sail back, and three times the thick ice (2)____ his way. He refused to give up, even when others said it was (3)____. At last a small boat lent by another country managed to break through the ice. As it came close to the shore, Shackleton stood on the deck and began to (4)____ the men one by one. To his great (5)____, every single man was still there, thin and weak but (6)____. Not one of them had died during the long (7)____. The men on the beach cheered and waved when they saw their leader (8)____. After two years of danger, the whole team was together again. Their (9)____ was proof of the trust between a leader and his men, and the world soon learned of their (10)____ return.', 164, 2, '[{"q":"1","answer":"A","options":["waiting","cooking","swimming","singing"],"explanation":"still waiting 仍在等待。"},{"q":"2","answer":"B","options":["opened","blocked","warmed","painted"],"explanation":"the ice blocked his way 冰挡住去路。"},{"q":"3","answer":"C","options":["easy","cheap","hopeless","funny"],"explanation":"said it was hopeless 说没希望了。"},{"q":"4","answer":"D","options":["throw","sell","bury","count"],"explanation":"count the men 一个个数人。"},{"q":"5","answer":"A","options":["joy","anger","fear","shame"],"explanation":"to his great joy 令他十分欣喜。"},{"q":"6","answer":"B","options":["asleep","alive","absent","lost"],"explanation":"weak but alive 虚弱却活着。"},{"q":"7","answer":"C","options":["meal","game","wait","race"],"explanation":"during the long wait 在漫长等待期间。"},{"q":"8","answer":"D","options":["leave","sink","fall","return"],"explanation":"saw their leader return 看到领袖归来。"},{"q":"9","answer":"A","options":["survival","failure","silence","holiday"],"explanation":"their survival 他们的生还。"},{"q":"10","answer":"B","options":["empty","safe","quick","loud"],"explanation":"their safe return 平安归来。"}]'::jsonb, 5, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective1', 'U3', 'A Letter to a Young Adventurer', 'Dear friend, you tell me that you dream of one day becoming an (1)____ and seeing wild, distant places. That is a fine dream, but let me give you some (2)____. First, never set out without careful planning. The most exciting trips can quickly turn into (3)____ when people are not prepared. Learn to read maps, to watch the weather, and to look after your own (4)____ in the cold. Second, choose your companions with (5)____. On a hard journey, the people around you matter more than any tool you (6)____. Third, remember that real courage is not the absence of (7)____. Brave explorers feel afraid too, but they keep going anyway. Finally, do not explore only to be (8)____. The best reason to set out is the wish to (9)____ something new about the world and about yourself. If you keep all this in mind, you will (10)____ the unknown with both excitement and care. Good luck, and travel wisely.', 161, 2, '[{"q":"1","answer":"C","options":["actor","farmer","explorer","driver"],"explanation":"becoming an explorer 成为探险家。"},{"q":"2","answer":"D","options":["money","food","music","advice"],"explanation":"give you some advice 给你一些建议。"},{"q":"3","answer":"A","options":["disaster","holiday","victory","comfort"],"explanation":"turn into disaster 变成灾难。"},{"q":"4","answer":"B","options":["phone","body","garden","shop"],"explanation":"look after your own body 照顾好自己的身体。"},{"q":"5","answer":"C","options":["anger","noise","care","speed"],"explanation":"choose with care 慎重选择。"},{"q":"6","answer":"D","options":["sell","bury","throw","carry"],"explanation":"any tool you carry 你带的任何工具。"},{"q":"7","answer":"A","options":["fear","sleep","snow","water"],"explanation":"the absence of fear 没有恐惧。"},{"q":"8","answer":"B","options":["tired","famous","cold","lost"],"explanation":"explore only to be famous 只为出名而探险。"},{"q":"9","answer":"C","options":["throw","sell","learn","lose"],"explanation":"learn something new 学到新东西。"},{"q":"10","answer":"D","options":["drop","paint","count","face"],"explanation":"face the unknown 面对未知。"}]'::jsonb, 6, 'sufe');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U3 听力·对话 Talking about a Hero', '上外版选择性必修第一册 U3 · dialogue', 3, 'Lily: I just finished reading about Ernest Shackleton. What an amazing explorer!
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U3 听力·独白 A Radio Report from the Ice', '上外版选择性必修第一册 U3 · passage', 2, 'Good evening. Tonight we look back at one of the greatest survival stories in history. In 1915 a ship became trapped in the frozen sea near Antarctica. For many months the crew waited in the freezing dark, hoping the ice would let them go. Instead, the moving ice crushed the wooden ship, and the men were left alone with only three small boats. They camped on the ice and drifted slowly north, never giving up hope of rescue. Their courage in the face of such danger still amazes us today.', '晚间节目回顾历史上最伟大的生还故事之一:1915年一艘船被困在南极附近结冰的海域;船员们在极冷的黑暗中等待数月,盼冰松开;然而移动的冰压碎了木船,只剩三条小艇;他们在冰上扎营、缓缓向北漂,从未放弃获救的希望;他们面对危险的勇气至今令人惊叹。', 'uk_male', '[{"q":"When did the ship become trapped?","type":"choice","answer":"D","options":["In 1815.","In 2015.","Last winter.","In 1915."]},{"q":"Where did this happen?","type":"choice","answer":"A","options":["In the frozen sea near Antarctica.","In a warm tropical bay.","On a quiet lake.","In a city harbour."]},{"q":"What finally happened to the ship?","type":"choice","answer":"B","options":["It sailed safely away.","The moving ice crushed it.","It was struck by lightning.","It was burned by the crew."]},{"q":"What did the men do after losing the ship?","type":"choice","answer":"C","options":["They flew home by plane.","They swam to the nearest city.","They camped on the ice and drifted north.","They stopped caring about rescue."]},{"q":"What does the speaker admire about the men?","type":"choice","answer":"D","options":["Their luck in finding gold.","Their skill at fishing.","Their fast wooden ship.","Their courage in great danger."]}]'::jsonb, '[]'::jsonb, 'short', 'elective1', 'U3', 'sufe');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U3 听力·对话 Planning a Polar Trip', '上外版选择性必修第一册 U3 · dialogue', 3, 'Anna: I''d love to join a polar expedition one day. Do you think I could?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U3 听力·独白 My First Voyage', '上外版选择性必修第一册 U3 · passage', 2, 'When I first went to sea, I was a young sailor who knew almost nothing about ships. On my second day a storm rose, and the waves looked as high as mountains. Each time the ship dived into the deep water between the waves, I was sure we would never come up again. I was so frightened that I promised to go straight home to my father and never sail again. But the next morning the wind died away and the sea became calm and beautiful. My fear faded as quickly as the storm, and soon I almost forgot all the promises I had made.', '我初次出海时是个对船几乎一无所知的年轻水手;第二天起了风暴,浪高如山;每当船扎进浪谷,我都以为再也起不来了;我吓得发誓要直接回家找父亲、再也不出海;但第二天早上风停了,海变得平静又美丽;我的恐惧随风暴一样迅速消退,很快就几乎忘了所有的誓言。', 'uk_male', '[{"q":"What was the speaker when this happened?","type":"choice","answer":"B","options":["An old sea captain.","A young, inexperienced sailor.","A famous explorer.","A ship builder."]},{"q":"What did the waves look like to him?","type":"choice","answer":"C","options":["As small as cups.","As flat as a road.","As high as mountains.","As warm as a bath."]},{"q":"How did he feel during the storm?","type":"choice","answer":"D","options":["Calm and happy.","Proud and bold.","Bored and sleepy.","Very frightened."]},{"q":"What did he promise during the storm?","type":"choice","answer":"A","options":["To go home and never sail again.","To buy a bigger ship.","To sail even further.","To become a captain."]},{"q":"What happened to his fear the next day?","type":"choice","answer":"B","options":["It became much worse.","It faded as the sea grew calm.","It stayed the same.","It turned into anger."]}]'::jsonb, '[]'::jsonb, 'short', 'elective1', 'U3', 'sufe');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U3 听力·对话 A Night at Camp', '上外版选择性必修第一册 U3 · dialogue', 3, 'Sam: It''s freezing tonight. I can hardly feel my hands.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U3 听力·独白 Why We Explore', '上外版选择性必修第一册 U3 · passage', 2, 'In this documentary we ask a simple question: why do people explore? Long ago, our ancestors wondered what lay beyond the distant hills and on the other side of the sky. That same wonder still moves us today. Some explorers want to gain knowledge and understand how the world works. Others simply wish to be the first to stand where no one has stood before. A few set out to test how much hardship they can bear. Exploring is rarely safe, yet people have never been willing to stay still. As long as an unknown world remains, someone will always want to set out and discover it.', '这部纪录片问一个简单的问题:人为何探险?很久以前,祖先们好奇远山之外、天空另一边有什么;同样的好奇至今驱动着我们;有的探险者想获取知识、理解世界如何运转;有的只想成为第一个站到无人到过之地的人;少数人出发是为了测试自己能承受多少艰难;探险很少安全,但人类从不愿安于现状;只要还有未知世界,总会有人想出发去发现它。', 'uk_male', '[{"q":"What question does the documentary ask?","type":"choice","answer":"D","options":["How do ships sink?","Where is the warmest sea?","Who built the first tent?","Why do people explore?"]},{"q":"What did our ancestors wonder about?","type":"choice","answer":"A","options":["What lay beyond the distant hills and the sky.","How to build large cities.","Which language to speak.","How to grow more food."]},{"q":"What is one reason given for exploring?","type":"choice","answer":"B","options":["To avoid learning anything new.","To gain knowledge and understand the world.","To stay safely at home.","To stop others from travelling."]},{"q":"What does the speaker say about safety?","type":"choice","answer":"C","options":["Exploring is completely safe.","Only machines are at risk.","Exploring is rarely safe.","Danger has disappeared today."]},{"q":"What will happen as long as an unknown world remains?","type":"choice","answer":"D","options":["People will stop being curious.","Exploring will become pointless.","Everyone will stay still.","Someone will always want to discover it."]}]'::jsonb, '[]'::jsonb, 'short', 'elective1', 'U3', 'sufe');
INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit, publisher) VALUES (11, 'Write a Brief Report on People''s Beliefs about Adventure(写一篇关于人们对探险看法的简短报告)', 'My Classmates'' Beliefs about Adventure', '你在班里做了一次关于''探险对你意味着什么''的小调查。请用英语写一篇约90-110词的简短报告,内容包括:① 用一句总体陈述说明同学们对探险的总体态度;② 用具体的百分比数字描述至少两类不同看法(如''见识新事物''''高风险活动''''说走就走的旅行''等);③ 用一句话作结。注意:数字要具体、相关、清楚,用来支撑你的陈述。', 'You have done a mini-survey in class about what adventure means to your classmates. Write a brief report (about 90-110 words) including: 1) a general statement about your classmates'' overall attitude towards adventure; 2) specific percentages describing at least two different views (e.g. seeing something new, highly risky activities, travelling on a budget); 3) a concluding sentence. Use statistics that are specific, relevant and clear to support your statement.', '["总体陈述(The majority of my classmates … / Most of my classmates hold a … attitude)","用具体百分比描述不同看法(45.2% of them said …; 26.8% described it as …)","数字具体、相关、清楚(避免 ''more than half'',用 ''52.4%'')","结尾句总结(It can thus be seen that …)"]'::jsonb, 70, 100, 'Last week I carried out a mini-survey in our class to find out what adventure means to my classmates. The results show that most of them hold a positive attitude towards adventure. As the figures show, 45.2% of the students said adventure meant "seeing and doing something new", while 28.6% described it as "getting off the beaten track and visiting unusual places". A smaller group, 16.7%, believed adventure was "taking part in highly risky activities", and only 9.5% related it to "travelling on a budget". It can thus be seen that, to most of my classmates, adventure is more about new experiences than about danger.', '【15 分制】A 档(13-15):五要素齐全、组织有条理、语言准确多样;B 档(10-12):要点较全、少量错误;C 档(7-9):要点偏少、句型简单;D 档(0-6):内容不完整、错误多。', '["Last week I carried out a mini-survey to find out what adventure means to my classmates.","As the figures show, 45.2% of the students said adventure meant seeing and doing something new.","A smaller group, 16.7%, believed adventure was taking part in highly risky activities.","It can thus be seen that adventure is more about new experiences than about danger."]'::jsonb, '[{"wrong":"More than half students think so.","correct":"More than half of the students think so.","note":"half of the + 复数名词;数字报告中更宜用具体百分比如 52.4%。"},{"wrong":"45.2% of students said adventure mean new things.","correct":"45.2% of the students said adventure meant new things.","note":"宾语从句用过去时 meant;百分比后通常加 of the。"},{"wrong":"The survey was carry out last week.","correct":"The survey was carried out last week.","note":"被动语态 be + 过去分词 carried out。"}]'::jsonb, '【探险看法调查报告结构】
INSERT INTO public.junior_grammar_tips (grade, volume, unit, content, publisher) VALUES (11, 'elective1', 'U3', '{"title":"被动语态·过去完成被动 & 过去进行被动速查","intro":"被动语态强调''动作的承受者''。本单元两大形式:过去某动作之前已被做完 → had been done(过去完成被动);过去某一时刻正在被做 → was/were being done(过去进行被动)。判断口诀:看时间状语——''之前/by then/before''用过去完成被动;''当时/when/while''用过去进行被动。","table":{"headers":["被动形式","结构 / 用法 / 例句"],"rows":[["过去完成被动","had been + 过去分词:过去动作A之前B已被完成。The ship had been crushed before they escaped."],["过去进行被动","was/were being + 过去分词:过去某刻正被进行。The boat was being repaired when the storm hit."],["by 短语","引出动作执行者:Every man had been chosen by Shackleton."],["含情态的被动","modal + be + 过去分词:Anyone left there would be starved to death."]]},"specialRules":[{"rule":"时间状语含 before / by the time / by 1915 / long before → 用过去完成被动 had been done","mark":"By 1915 the ship had been surrounded by ice."},{"rule":"时间状语含 when / while / at that moment / as → 用过去进行被动 was/were being done","mark":"Efforts were being made when the ice broke."},{"rule":"主语是动作的承受者才用被动;若主语自己发出动作,用主动","mark":"The men were marching(主动)vs The route was being explored(被动)"},{"rule":"情态动词的被动:would/might/must + be + done;对过去推测 might have been + done","mark":"Without him, the men might have been lost."}],"why":["用被动是为了把焦点放在''受动作影响的人或事''上,或在不知道/不必说出执行者时使用。had been done 表''过去之前已完成''的被动,was/were being done 表''过去那一刻正在进行''的被动——时态由对应的过去时被动而来。"],"gaokaoPoints":["语法填空高频:给动词原形,据时间状语(before/by then vs when/while)判断填 had been done 还是 was/were being done。","辨析过去完成被动 vs 过去进行被动 vs 一般过去被动(was/were done);by 短语引出执行者;含情态被动 modal + be done。"],"examVsReal":[{"exam":"The boat was being repaired when the storm hit.(考试规范被动)","real":"They were repairing the boat when the storm hit.","note":"口语里常用主动更直接;考试为强调受动者或客观叙述常用被动。"},{"exam":"The route had never been crossed before.(过去完成被动)","real":"No one had ever crossed the route before.","note":"真实英语两种都地道;考试常借被动考''过去之前已完成''这一时间关系。"}]}'::jsonb, 'sufe');
